28		pid, e1 := setupPatientEncounter(t, s)
29		e2enc, err := s.AddEncounter(doc, pid, clk.t.Add(2*time.Hour))
30		if err != nil {
31			t.Fatal(err)
32		}
33	
34		mkDiag := func(eid ID, content string) ID {
35			t.Helper()
36			r, err := s.CreateDraft(doc, pid, eid, Diagnosis, content)
37			if err != nil {
38				t.Fatal(err)
39			}
40			if _, err := s.ActivateRecord(doc, r.ID); err != nil {
41				t.Fatal(err)
42			}
43			return r.ID
44		}
45		r1 := mkDiag(e1, "诊断1")
46		r2 := mkDiag(e1, "诊断2")
47		e2rec := mkDiag(e2enc.ID, "二诊诊断")
