49		o, err := s.CreateDraft(doc, pid, e1, Order, "医嘱1")
50		if err != nil {
51			t.Fatal(err)
52		}
53		if _, err := s.ActivateRecord(doc, o.ID); err != nil {
54			t.Fatal(err)
55		}
56		dr, err := s.CreateDraft(doc, pid, e1, Diagnosis, "未生效草稿")
57		if err != nil {
58			t.Fatal(err)
59		}
60	
61		chart, _ := s.Chart(doc, pid)
62		var r1v1 Version
63		for _, h := range chart.Records {
64			if h.Record.ID == r1 {
65				r1v1 = *h.CurrentVersion
66			}
67		}
68	
69		return selectiveFixture{
70			s: s, clk: clk, pid: pid, e1: e1, e2: e2enc.ID,
71			r1: r1, r2: r2, r1v1: r1v1, r3: o.ID, draft: dr.ID, e2rec: e2rec,
72			start: clk.t.Add(-time.Hour), end: clk.t.Add(24 * time.Hour),
73		}
