38			return Encounter{}, ErrAccessDenied
39		}
40		if patientID == "" {
41			return Encounter{}, fmt.Errorf("%w: patient id is required", ErrInvalidArgument)
42		}
43	
44		var result Encounter
45		err := s.mutate(func(snap *snapshot) error {
46			p, err := requireActivePatient(snap, patientID)
47			if err != nil {
48				return err
49			}
50			at := occurredAt
51			if at.IsZero() {
52				at = s.now()
53			}
54			e := &Encounter{
55				ID:         newID("enc"),
56				PatientID:  p.ID,
57				OccurredAt: at.UTC(),
58				CreatedAt:  s.now(),
59			}
60			snap.Encounters[e.ID] = e
61			result = *e
62			return nil
63		})
64		return result, err
65	}
66	
67	// DeactivatePatient 停用患者档案。停用后不能新增就诊、改动草稿、使记录生效、
68	// 进行更正或新建授权，接收方也无法继续读取；内部使用者仍可查看全部历史。
69	//
70	// 重复停用返回成功且不产生额外变化（不新增审计事件）。
71	func (s *Store) DeactivatePatient(actor Actor, patientID ID) error {
72		if !actor.valid() || !actor.IsInternal() {
73			return ErrAccessDenied
74		}
75		return s.mutate(func(snap *snapshot) error {
76			p, err := requirePatient(snap, patientID)
77			if err != nil {
78				return err
79			}
80			if p.Deactivated {
81				// 幂等：正式保存的患者状态已经是停用。确认已有结果即可——保持首次
82				// 停用的时间与操作身份，不生成额外变化或事件，也不落盘：重复确认不
83				// 依赖当前能否写入本地数据，任何内部使用者的合法确认都得到同一结果，
84				// 且不能把首次停用改成确认者的信息。一次保存失败的停用尝试不会改变
85				// 正式状态，因此不会被当作成功依据。
86				return errUnchanged
87			}
88			now := s.now()
89			p.Deactivated = true
90			s.addAudit(snap, p.ID, actor, ActionDeactivated, "patient", p.ID, now)
91			return nil
92		})
93	}
94	
95	// GetPatient 返回患者档案。仅供内部使用者。
96	func (s *Store) GetPatient(actor Actor, patientID ID) (Patient, error) {
97		if !actor.valid() || !actor.IsInternal() {
98			return Patient{}, ErrAccessDenied
99		}
100		var result Patient
101		err := s.view(func(snap *snapshot) error {
102			p, err := requirePatient(snap, patientID)
103			if err != nil {
104				return err
105			}
106			result = *p
107			return nil
108		})
109		return result, err
110	}
111	
112	// ListEncounters 按发生时间顺序返回患者的全部就诊。仅供内部使用者。
113	func (s *Store) ListEncounters(actor Actor, patientID ID) ([]Encounter, error) {
114		if !actor.valid() || !actor.IsInternal() {
115			return nil, ErrAccessDenied
116		}
117		var result []Encounter
118		err := s.view(func(snap *snapshot) error {
119			if _, err := requirePatient(snap, patientID); err != nil {
120				return err
121			}
122			for _, e := range snap.Encounters {
123				if e.PatientID == patientID {
124					result = append(result, *e)
125				}
126			}
127			sortEncounters(result)
128			return nil
129		})
130		return result, err
131	}
132	
133	func requirePatient(snap *snapshot, patientID ID) (*Patient, error) {
134		p := snap.Patients[patientID]
135		if p == nil {
136			return nil, fmt.Errorf("%w: patient %q", ErrNotFound, patientID)
137		}
138		return p, nil
139	}
140	
141	func requireActivePatient(snap *snapshot, patientID ID) (*Patient, error) {
142		p, err := requirePatient(snap, patientID)
143		if err != nil {
144			return nil, err
145		}
146		if p.Deactivated {
147			return nil, fmt.Errorf("%w: patient %q", ErrDeactivated, patientID)
148		}
149		return p, nil
150	}
151	
152	// requireEncounter 校验就诊存在且属于给定患者。
153	// 引用不存在的就诊返回 ErrNotFound；就诊属于其他患者返回 ErrMismatchedPatient。
154	func requireEncounter(snap *snapshot, patientID, encounterID ID) (*Encounter, error) {
155		e := snap.Encounters[encounterID]
156		if e == nil {
157			return nil, fmt.Errorf("%w: encounter %q", ErrNotFound, encounterID)
158		}
159		if patientID != "" && e.PatientID != patientID {
160			return nil, fmt.Errorf("%w: encounter %q belongs to patient %q, not %q",
161				ErrMismatchedPatient, encounterID, e.PatientID, patientID)
162		}
163		return e, nil
164	}
165	
166	func validCategory(c string) bool { return c == Diagnosis || c == Order }
